import React from "react";
import { Link } from "react-router-dom";

const Navbar = () => {
  return (
    <nav className="bg-black bg-opacity-80 text-blue-200 px-8 py-4 shadow-md">
      <div className="flex justify-between items-center w-full max-w-screen-xl mx-auto">
        {/* Logo */}
        <div className="text-2xl font-bold">🎮 Gamify</div>

        {/* Horizontal Nav Links with space */}
        <div className="flex flex-row gap-10 text-lg font-medium">
          <Link to="/register" className="hover:text-white transition">Register</Link>
          <Link to="/login" className="hover:text-white transition">Login</Link>
          <Link to="/courses" className="hover:text-white transition">Courses</Link>
          <Link to="/leaderboard" className="hover:text-white transition">Leaderboard</Link>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
